<div class="page-heading"><div><p class="eyebrow">THE SHOP AT A GLANCE</p><h1>Ready for the next cue.</h1><p class="text-secondary">Your shows, equipment, and shop priorities, in one workspace.</p></div><div class="page-actions"><a href="/reports/timeline" data-workspace class="btn">View timeline</a><?php if (App\Middleware\Permissions::allows('shows.edit')): ?><a href="/shows/add" data-workspace class="btn btn-primary"><span class="material-symbols-rounded" aria-hidden="true">add</span>Add show</a><?php endif; ?></div></div>
<div class="widget-grid"><?php foreach ($widgets as [$label,$count,$url,$icon]): ?><section class="card floating-card stat-card" data-card-key="widget-<?= e($icon) ?>"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true"><?= e($icon) ?></span><?= e($label) ?></h2><div class="card-body"><div class="stat-number"><?= e($count) ?></div><a href="<?= e($url) ?>" data-workspace>Open workspace <span class="material-symbols-rounded" aria-hidden="true">arrow_forward</span></a></div></section><?php endforeach; ?></div>
<div class="dashboard-grid"><section class="card floating-card" data-card-key="upcoming"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">event</span>On the horizon</h2><div class="card-body"><?php if (!$upcoming): ?><div class="empty-state"><span class="material-symbols-rounded" aria-hidden="true">theater_comedy</span><h3>Your next show starts here.</h3><p>Create a show, add its shop orders, and get the shop ready.</p></div><?php endif; ?><?php foreach ($upcoming as $item): ?><a class="record-row" href="/shows/<?= e($item['id']) ?>" data-workspace><div><strong><?= e($item['name']) ?></strong><small><?= e($item['theatre']) ?> | Prep <?= e($item['prep_start']) ?></small></div><span class="badge bg-blue-lt"><?= e($item['status']) ?></span></a><?php endforeach; ?></div></section>
<section class="card floating-card" data-card-key="activity"><h2 class="floating-label"><span class="material-symbols-rounded" aria-hidden="true">history</span>Recent activity</h2><div class="card-body"><?php if (!$activity): ?><p class="text-secondary">Shop activity appears here as work begins.</p><?php endif; ?><?php foreach ($activity as $event): ?><div class="activity-row"><span class="activity-dot"></span><div><strong><?= e(ucwords(str_replace('.',' ',$event['action']))) ?></strong><small><?= e($event['user_name'] ?? 'System') ?> | <?= e($event['created_at']) ?> UTC</small></div></div><?php endforeach; ?></div></section></div>
<?php if ($shortages): ?><section class="card floating-card" data-card-key="shortages"><h2 class="floating-label">Planning shortages: next 30 days</h2><div class="card-body"><?php foreach ($shortages as $shortage): ?><p><?= e($shortage['name']) ?>: <?= e($shortage['shortage']) ?> short at peak demand.</p><?php endforeach; ?></div></section><?php endif; ?>
